// Usage: node 3ds/tools/bundle_story.js  → writes 3ds/romfs/story.js
// Concatenates the shim, the web version's story/data/core files (unmodified) and the headless runtime.
const fs = require("fs"), path = require("path");
const root = path.join(__dirname, "..", "..");
const files = ["3ds/js/shim.js", "js/data.js", "js/core.js", "js/dsl.js", "js/story/part1.js", "js/story/part2.js", "js/story/part3.js", "js/story/bonus.js", "js/story/endings.js", "3ds/js/rt.js", "3ds/js/flat.js"];
let out = "/* GENERATED by 3ds/tools/bundle_story.js — do not edit. */\n";
for (const f of files) out += `\n/* ===== ${f} ===== */\n` + fs.readFileSync(path.join(root, f), "utf8") + "\n";
out += "\nVN.compile();\n";
fs.mkdirSync(path.join(__dirname, "..", "romfs"), { recursive: true });
fs.writeFileSync(path.join(__dirname, "..", "romfs", "story.js"), out);
console.log("story.js", (out.length / 1024).toFixed(0) + " KB");
